package com.bank.accrual;

// Sweeps account balances applying daily interest.
// Two versions: one that starves safepoints, one that is safepoint-friendly.
class AccrualEngine {
    private final double dailyRate;

    AccrualEngine(double dailyRate) { this.dailyRate = dailyRate; }

    // BAD: one giant int-counted loop. The JIT may omit the safepoint poll,
    // so a GC request cannot interrupt this thread until the loop ends.
    double sweepBad(double[] balances) {
        double total = 0.0;
        for (int i = 0; i < balances.length; i++) {
            balances[i] += balances[i] * dailyRate;
            total += balances[i];
        }
        return total;
    }

    // GOOD: process in bounded chunks. The outer boundary and method structure
    // give the JIT natural places to keep safepoint polls, so a GC request
    // can be honoured between chunks instead of after the whole array.
    double sweepGood(double[] balances) {
        double total = 0.0;
        int chunk = 10_000;
        for (int start = 0; start < balances.length; start += chunk) {
            int end = Math.min(start + chunk, balances.length);
            total += sweepChunk(balances, start, end); // method return = poll point
        }
        return total;
    }

    private double sweepChunk(double[] balances, int start, int end) {
        double sub = 0.0;
        for (int i = start; i < end; i++) {
            balances[i] += balances[i] * dailyRate;
            sub += balances[i];
        }
        return sub;
    }
}
