package com.bank.accrual;

import java.util.concurrent.atomic.AtomicLong;

// A background heartbeat that records the longest gap between ticks.
// A long gap means this thread was frozen waiting at a safepoint while
// another thread refused to reach one.
class StallProbe implements Runnable {
    private volatile boolean running = true;
    private final AtomicLong maxStallMillis = new AtomicLong(0);

    @Override public void run() {
        long last = System.nanoTime();
        while (running) {
            long now = System.nanoTime();
            long gapMs = (now - last) / 1_000_000;
            maxStallMillis.accumulateAndGet(gapMs, Math::max);
            last = now;
            // allocate a little so the JVM wants to GC → forces safepoints
            byte[] churn = new byte[1024];
            if (churn.length < 0) System.out.print(""); // prevent elision
        }
    }

    void stop() { running = false; }
    long maxStallMillis() { return maxStallMillis.get(); }
}
