package com.bank.accrual;

import java.util.logging.*;

public class SafepointDemo {
    private static final Logger log = Logger.getLogger(SafepointDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws InterruptedException {
        AccrualEngine engine = new AccrualEngine(0.0002); // ~0.02% daily
        int accounts = 50_000_000;
        double[] balances = new double[accounts];
        for (int i = 0; i < accounts; i++) balances[i] = 1000.0 + (i % 5000);

        log.info(() -> "Loaded " + accounts + " account balances.");

        // Measure stall caused by the BAD sweep.
        StallProbe badProbe = new StallProbe();
        Thread t1 = new Thread(badProbe, "probe-bad");
        t1.start();
        long s1 = System.currentTimeMillis();
        double totalBad = engine.sweepBad(balances.clone());
        long d1 = System.currentTimeMillis() - s1;
        Thread.sleep(50);
        badProbe.stop(); t1.join();
        log.warning(() -> "BAD sweep: took " + d1 + "ms, max probe stall "
                + badProbe.maxStallMillis() + "ms (safepoint starvation), total=" + Math.round(totalBad));

        // Measure stall caused by the GOOD sweep.
        StallProbe goodProbe = new StallProbe();
        Thread t2 = new Thread(goodProbe, "probe-good");
        t2.start();
        long s2 = System.currentTimeMillis();
        double totalGood = engine.sweepGood(balances.clone());
        long d2 = System.currentTimeMillis() - s2;
        Thread.sleep(50);
        goodProbe.stop(); t2.join();
        log.info(() -> "GOOD sweep: took " + d2 + "ms, max probe stall "
                + goodProbe.maxStallMillis() + "ms (safepoint-friendly), total=" + Math.round(totalGood));
    }
}

